select userId,caseNo,userName,userPhone,type,state,createTime,isFined, promoterName, promoterPhone, isTestcase from (
select la.user_id as userId, la.loan_no as caseNo, la.user_name as userName, la.user_Phone as userPhone, 2 as type, la.state as state,la.create_time as createTime, la.is_fined as isFined, la.user_promoted_name as promoterName, la.user_promoted_phone as promoterPhone, la.is_test_case as isTestcase from loan_application la where 1= 1 and la.delete_flag != 1
and la.user_name like CONCAT(CONCAT('%',#{userName,jdbcType=VARCHAR}), '%')
and la.loan_no like CONCAT(CONCAT('%',#{caseNo,jdbcType=VARCHAR}), '%')
and la.state = #{state,jdbcType=INTEGER}
and la.is_fined = #{isFined,jdbcType=INTEGER}
and la.user_promoted_name like CONCAT(CONCAT('%',#{promoterName,jdbcType=VARCHAR}), '%')
and la.user_promoted_phone like CONCAT(CONCAT('%',#{promoterPhone,jdbcType=VARCHAR}), '%')
and la.is_fined is null
and la.is_test_case = #{isTestcase,jdbcType=INTEGER}
and la.is_test_case = 0
and la.is_test_case = 1
union all select aa.user_id as userId, aa.agent_no as caseNo,aa.user_name as userName, aa.user_Phone as userPhone, 1 as type,aa.state as state, aa.create_time as createTime, aa.is_fined as isFined, aa.user_promoted_name as promoterName, aa.user_promoted_phone as promoterPhone, aa.is_test_case as isTestcase from agent_apply aa where 1= 1 and aa.delete_flag != 1
and aa.user_name like CONCAT(CONCAT('%',#{userName,jdbcType=VARCHAR}), '%')
and aa.agent_no like CONCAT(CONCAT('%',#{caseNo,jdbcType=VARCHAR}), '%')
and aa.state = #{state,jdbcType=INTEGER}
and aa.is_fined = #{isFined,jdbcType=INTEGER}
and aa.user_promoted_name like CONCAT(CONCAT('%',#{promoterName,jdbcType=VARCHAR}), '%')
and aa.user_promoted_phone like CONCAT(CONCAT('%',#{promoterPhone,jdbcType=VARCHAR}), '%')
and aa.is_fined is null
and aa.is_test_case = #{isTestcase,jdbcType=INTEGER}
and aa.is_test_case = 0
and aa.is_test_case = 1
select aa.user_id as userId, aa.agent_no as caseNo,aa.user_name as userName, aa.user_Phone as userPhone, 1 as type,aa.state as state, aa.create_time as createTime, aa.is_fined as isFined, aa.user_promoted_name as promoterName, aa.user_promoted_phone as promoterPhone, aa.is_test_case as isTestcase from agent_apply aa where 1= 1 and aa.delete_flag != 1
and aa.user_name like CONCAT(CONCAT('%',#{userName,jdbcType=VARCHAR}), '%')
and aa.agent_no like CONCAT(CONCAT('%',#{caseNo,jdbcType=VARCHAR}), '%')
and aa.state = #{state,jdbcType=INTEGER}
and aa.is_fined = #{isFined,jdbcType=INTEGER}
and aa.user_promoted_name like CONCAT(CONCAT('%',#{promoterName,jdbcType=VARCHAR}), '%')
and aa.user_promoted_phone like CONCAT(CONCAT('%',#{promoterPhone,jdbcType=VARCHAR}), '%')
and aa.is_fined is null
and aa.is_test_case = #{isTestcase,jdbcType=INTEGER}
and aa.is_test_case = 0
and aa.is_test_case = 1
select la.user_id as userId, la.loan_no as caseNo, la.user_name as userName, la.user_Phone as userPhone, 2 as type, la.state as state,la.create_time as createTime, la.is_fined as isFined, la.user_promoted_name as promoterName, la.user_promoted_phone as promoterPhone.la.is_test_case as isTestcase from loan_application la where 1= 1 and la.delete_flag != 1
and la.user_name like CONCAT(CONCAT('%',#{userName,jdbcType=VARCHAR}), '%')
and la.loan_no like CONCAT(CONCAT('%',#{caseNo,jdbcType=VARCHAR}), '%')
and la.state = #{state,jdbcType=INTEGER}
and la.is_fined = #{isFined,jdbcType=INTEGER}
and la.user_promoted_name like CONCAT(CONCAT('%',#{promoterName,jdbcType=VARCHAR}), '%')
and la.user_promoted_phone like CONCAT(CONCAT('%',#{promoterPhone,jdbcType=VARCHAR}), '%')
and la.is_fined is null
and la.is_test_case = #{isTestcase,jdbcType=INTEGER}
and la.is_test_case = 0
and la.is_test_case = 1
) a ORDER BY createTime DESC limit #{pageIndex}, #{pageSize};
